const CATS=[['block','حجب وخصوصية','shield','var(--teal)','حاجبات الإعلانات وحماية من التتبع'],['vpn','VPN وبروكسي','compass','var(--coral)','لتغيير عنوان IP وفتح المواقع المحجوبة'],['dl','تحميل وصور','out','var(--gold)','مدير التحميل وحفظ الصور بأي صيغة'],['pdf','PDF وقراءة','book','var(--sky)','قراءة PDF وتعديله وتظليل المقالات'],['translate','ترجمة','globe','var(--coral)','ترجمة الصفحات والملفات أثناء التصفح'],['eyes','راحة العين','moon','var(--teal)','وضع داكن وتقليل إجهاد العين أمام الشاشة'],['tools','أدوات وتصميم','code','var(--violet)','أدوات مساعدة أثناء التصفح والتصميم']];
